// Generic bech32 string layer: the character-level validation, the separator
// hunt and the checksum gate. Knows nothing about segwit.

import {
  CHARSET,
  CHECKSUM_LENGTH,
  MAX_HRP_LENGTH,
  charsetIndex,
  isCharsetChar,
} from './charset.mjs';
import { bech32CreateChecksum, bech32VerifyChecksum } from './checksum.mjs';
import { isMixedCase, isPrintableAsciiRange } from '../python/text.mjs';

/** What a failed decode yields: Python's `(None, None)`. */
function failure() {
  return [null, null];
}

/**
 * Validate a bech32 string and split it into `[hrp, data]`, or `[null, null]`.
 *
 * `data` excludes the six checksum symbols. The HRP is returned lower-cased,
 * so an all-upper-case address never matches an upper-case HRP argument.
 */
export function bech32Decode(bech) {
  if (!isPrintableAsciiRange(bech) || isMixedCase(bech)) {
    return failure();
  }

  const lowered = bech.toLowerCase();
  const pos = lowered.lastIndexOf('1');
  // `pos` is both the separator index and the HRP length.
  if (pos < 1 || pos + 1 + CHECKSUM_LENGTH > lowered.length || pos > MAX_HRP_LENGTH) {
    return failure();
  }

  const tail = lowered.slice(pos + 1);
  for (const char of tail) {
    if (!isCharsetChar(char)) {
      return failure();
    }
  }

  const hrp = lowered.slice(0, pos);
  const data = [];
  for (const char of tail) {
    data.push(charsetIndex(char));
  }
  if (!bech32VerifyChecksum(hrp, data)) {
    return failure();
  }
  return [hrp, data.slice(0, -CHECKSUM_LENGTH)];
}

/** Compute a bech32 string from an HRP and 5-bit data values. */
export function bech32Encode(hrp, data) {
  const combined = [...data, ...bech32CreateChecksum(hrp, data)];
  return `${hrp}1${combined.map((value) => CHARSET[value]).join('')}`;
}
