// Segwit address layer -- `bech32.decode` / `bech32.encode`.
//
// This mirrors the BIP-173-only behaviour of the reference module: a witness
// version of 1..16 is accepted with an ordinary bech32 checksum, and bech32m
// (BIP-350) strings are rejected outright.

import { bech32Decode, bech32Encode } from './codec.mjs';
import { convertbits } from './convert.mjs';

export const MIN_PROGRAM_LENGTH = 2;
export const MAX_PROGRAM_LENGTH = 40;
export const MAX_WITNESS_VERSION = 16;

function failure() {
  return [null, null];
}

/**
 * Decode a segwit address into `[witnessVersion, witnessProgram]`, where the
 * program is a plain array of byte values, or `[null, null]` on any failure.
 *
 * The program-length check deliberately precedes the `data[0]` read: for a
 * checksum-only string the payload is empty, the conversion yields `[]`, and the
 * length test bails out before the witness version would be indexed.
 */
export function decode(hrp, addr) {
  const [hrpGot, data] = bech32Decode(addr);
  if (hrpGot !== hrp) {
    return failure();
  }

  const decoded = convertbits(data.slice(1), 5, 8, false);
  if (
    decoded === null ||
    decoded.length < MIN_PROGRAM_LENGTH ||
    decoded.length > MAX_PROGRAM_LENGTH
  ) {
    return failure();
  }
  if (data[0] > MAX_WITNESS_VERSION) {
    return failure();
  }
  if (data[0] === 0 && decoded.length !== 20 && decoded.length !== 32) {
    return failure();
  }
  return [data[0], decoded];
}

/** Encode a segwit address, or `null` when the result would not round-trip. */
export function encode(hrp, witver, witprog) {
  const addr = bech32Encode(hrp, [witver, ...convertbits(witprog, 8, 5)]);
  const [version, program] = decode(hrp, addr);
  if (version === null && program === null) {
    return null;
  }
  return addr;
}

// Python `str` primitives that bech32's decoder depends on.
//
// `bech32_decode` inspects its input one code point at a time and compares the
// string against its own `lower()`/`upper()` forms, so these helpers reproduce
// those exact semantics rather than approximating them.

/**
 * Ordinals of a string, iterated the way Python iterates a `str`:
 * one entry per code point, not per UTF-16 unit.
 */
export function codePoints(text) {
  const points = [];
  for (const char of text) {
    points.push(char.codePointAt(0));
  }
  return points;
}

/** Python's `not any(ord(x) < 33 or ord(x) > 126 for x in text)`. */
export function isPrintableAsciiRange(text) {
  for (const char of text) {
    const point = char.codePointAt(0);
    if (point < 33 || point > 126) {
      return false;
    }
  }
  return true;
}

/**
 * Python's `text.lower() != text and text.upper() != text`.
 *
 * A string with no cased characters at all (e.g. "1231PQYPQA3AQ5Z" has none in
 * its digits, but its letters are all upper) is *not* mixed case, which is why
 * both halves of the conjunction matter. Callers reject non-ASCII input first,
 * so ASCII case mapping is the only behaviour exercised here.
 */
export function isMixedCase(text) {
  return text.toLowerCase() !== text && text.toUpperCase() !== text;
}
// Python's `repr()` for the value shapes this program prints: int, None and
// list-of-int. `print(x)` uses `str(x)`, which for all of these equals `repr(x)`.

export function pyRepr(value) {
  if (value === null || value === undefined) {
    return 'None';
  }
  if (Array.isArray(value)) {
    return `[${value.map(pyRepr).join(', ')}]`;
  }
  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }
  if (typeof value === 'string') {
    return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
  }
  return String(value);
}
// Python's `print` / `sys.stderr.write` mapped onto Node's streams.
//
// Nothing here calls `process.exit()`. The entry point sets `process.exitCode`
// and returns instead, so Node always drains stdout/stderr before terminating --
// `process.exit()` truncates pipes because those streams are asynchronous.

export function writeStdout(text) {
  process.stdout.write(text);
}

export function writeStderr(text) {
  process.stderr.write(text);
}

/** `print(value)` -- the text followed by a single newline. */
export function print(text) {
  writeStdout(`${text}\n`);
}

