// Round 3: systematic separator tampering (insert / overwrite / delete a '1' at
// every index of known-good addresses) plus a seeded fuzz over separator-rich
// alphabets. Appends to /tmp/corpus/separator-edge.json.
import { writeFileSync, readFileSync } from 'node:fs';
import { segwitEncode, bech32Encode } from '/tmp/probe/gen.mjs';

const cases = JSON.parse(readFileSync('/tmp/corpus/separator-edge.json', 'utf8'));
const seen = new Set(cases.map((c) => JSON.stringify(c)));
const add = (...argv) => {
  const key = JSON.stringify(argv);
  if (seen.has(key)) return;
  seen.add(key);
  cases.push(argv);
};
const ab = (a, b) => add('--a', a, '--b', b);
const withDerivedHrp = (s) => {
  const pos = s.lastIndexOf('1');
  ab(pos < 0 ? '' : s.slice(0, pos), s);
};

const P20 = Array.from({ length: 20 }, (_, i) => (i * 7) % 256);
const bases = [
  ['bc', segwitEncode('bc', 1, [8, 128])],
  ['bc', segwitEncode('bc', 0, P20)],
  ['bc', 'bc1gmk9yu'],
  ['a1b', segwitEncode('a1b', 1, [8, 128])],
  ['1', segwitEncode('1', 1, [8, 128])],
  ['q'.repeat(83), segwitEncode('q'.repeat(83), 1, [8, 128])],
  ['bc1', segwitEncode('bc1', 16, [255, 192])],
  ['', bech32Encode('', [1, 0, 0, 0, 0])],
];

// ---- insert / overwrite / delete a '1' at every index
for (const [hrp, addr] of bases) {
  for (let i = 0; i <= addr.length; i += 1) {
    const inserted = addr.slice(0, i) + '1' + addr.slice(i);
    ab(hrp, inserted);
    withDerivedHrp(inserted);
    if (i < addr.length) {
      const over = addr.slice(0, i) + '1' + addr.slice(i + 1);
      ab(hrp, over);
      withDerivedHrp(over);
      const del = addr.slice(0, i) + addr.slice(i + 1);
      ab(hrp, del);
      withDerivedHrp(del);
    }
  }
  // strip every '1' out entirely
  ab(hrp, addr.split('1').join(''));
  ab(hrp, addr.split('1').join('q'));
  ab(hrp, `1${addr}`);
  ab(hrp, `${addr}1`);
  ab(hrp, `1${addr}1`);
  ab(`1${hrp}`, `1${addr}`);
}

// ---- seeded fuzz (xorshift32) over separator-rich alphabets
let state = 0x1a2b3c4d;
const rnd = () => {
  state ^= state << 13; state >>>= 0;
  state ^= state >>> 17;
  state ^= state << 5; state >>>= 0;
  return state / 0x100000000;
};
const alphabets = [
  '11qp',                 // separators + valid symbols
  '11qpbio',              // + characters absent from CHARSET
  '11QPqpBI',             // + case mixing
  '11qp ~!-',             // + punctuation and a space (space is < 33 -> reject)
  '1qpzry9x8gf2tvdw0s3jn54khce6mua7l',
  '111',                  // separators only
];
for (const alpha of alphabets) {
  for (let i = 0; i < 320; i += 1) {
    const len = 1 + Math.floor(rnd() * 24);
    let s = '';
    for (let k = 0; k < len; k += 1) s += alpha[Math.floor(rnd() * alpha.length)];
    withDerivedHrp(s);
    if (i % 4 === 0) ab('bc', s);
    if (i % 7 === 0) ab('q', s);
  }
}

